    """Saves to JSON. Simple append logic."""
    entry = {"source": source, "content": text}
    data = []
    if os.path.exists(LOG_FILE):
        with open(LOG_FILE, 'r') as f:
            try: data = json.load(f)
            except: data = []

    data.append(entry)
    with open(LOG_FILE, 'w') as f:
